query:
query {
  rateLimit { remaining resetAt }
  repository(owner:"sparq-org",name:"sparq") {
    defaultBranchRef { target { oid } }
    pullRequest(number:6095) {
      id number state headRefOid headRefName baseRefName isDraft mergeable mergeStateStatus body reviewDecision
      autoMergeRequest { enabledAt enabledBy { login } }
      mergeQueueEntry { position state headCommit { oid } }
      labels(first:30) { nodes { name } pageInfo { hasNextPage } }
      timelineItems(last:100,itemTypes:[LABELED_EVENT,UNLABELED_EVENT]) {
        pageInfo { hasPreviousPage }
        nodes {
          __typename
          ... on LabeledEvent { createdAt actor { login } label { name } }
          ... on UnlabeledEvent { createdAt actor { login } label { name } }
        }
      }
      comments(last:50) { pageInfo { hasPreviousPage } nodes { author { login } body url } }
      reviews(last:30) { pageInfo { hasPreviousPage } nodes { author { login } state commit { oid } body } }
      reviewThreads(first:50) {
        pageInfo { hasNextPage }
        nodes { id isResolved isOutdated comments(first:10) { pageInfo { hasNextPage } nodes { author { login } body url path line } } }
      }
    }
    issue(number:4567) {
      state labels(first:30) { nodes { name } pageInfo { hasNextPage } }
      comments(last:30) { pageInfo { hasPreviousPage } nodes { author { login } body url } }
    }
    mergeQueue { entries(first:10) { pageInfo { hasNextPage } nodes { position state pullRequest { number headRefOid } } } }
  }
}
